def palindrome_pairs(words):
    def is_palindrome(s):
        return s == s[::-1]

    root = {}
    for idx, word in enumerate(words):
        node = root
        for i in range(len(word) - 1, -1, -1):
            ch = word[i]
            if is_palindrome(word[:i + 1]):
                node.setdefault('pal_prefix_indices', []).append(idx)
            node = node.setdefault(ch, {})
        node['word_index'] = idx
        node.setdefault('pal_prefix_indices', [])

    result = []
    for idx, word in enumerate(words):
        node = root
        n = len(word)
        for i in range(n):
            if node.get('word_index', -1) != -1 and node['word_index'] != idx and is_palindrome(word[i:]):
                result.append([idx, node['word_index']])
            ch = word[i]
            if ch not in node:
                break
            node = node[ch]
        else:
            if node.get('word_index', -1) != -1 and node['word_index'] != idx:
                result.append([idx, node['word_index']])
            for other_idx in node.get('pal_prefix_indices', []):
                if other_idx != idx:
                    result.append([idx, other_idx])

    result.sort()
    return result

